// Capture interaction specification. Illustrative pixels only; no OS capture.
// Live-capture contract: retain the selection boundary and show the adjacent
// preview/control windows immediately. A pending first frame has an explicit
// loading state; startup failure restores the frozen selection for retry.
// A stable source permits the next automatic scroll even if a join is pending.
// Pending joins are retained for completion/recovery, never a stability gate.
// Keep the boundary and adjacent controls visible to desktop sharing as well.
// Exclude only a controller that actually overlaps the source pixels.
function modeButton(action,icon,label){return `<button data-action="${action}" title="${label}" aria-label="${label}">${toolbarIcon(icon)}</button>`;}
function captureModeBar(){if(state.localImage||state.editingPin||state.colorOnly)return '';return `<nav class="capture-mode-bar" aria-label="截图模式">${[['capture','截图'],['scroll','滚动长截图（待验收）'],['record','录屏']].map(([mode,label])=>`<button data-mode="${mode}" class="${(state.captureMode||'capture')===mode?'active':''}">${label}</button>`).join('')}</nav>`;}
function captureModeControls(){const recording=state.captureMode==='record';return `<div class="capture-mode-setup"><button class="primary" data-action="${recording?'record-plan':'scroll-plan'}">${recording?'开始录制':'开始滚动截图'}</button>${recording?`<div class="row"><label>格式 <select id="record-format"><option>MP4</option><option>GIF</option></select></label><label><input id="record-cursor" type="checkbox" checked>鼠标指针</label><label><input id="record-audio" type="checkbox">系统声音</label><label><input id="record-mic" type="checkbox">麦克风</label></div>`:'<small class="scroll-incomplete-notice">缓慢滚动选区即自动拼接，右侧实时预览长图；可随时复制、保存或编辑。正在真实环境验收，如遇问题请反馈。</small>'}<button data-action="cancel-capture">取消</button></div>`;}
function sourceBox(){const r=state.selection||{x:160,y:140,w:660,h:400},b=$('#capture-surface')?.getBoundingClientRect();return {x:r.x+(b?.x||0),y:r.y+(b?.y||56),w:r.w,h:r.h};}
function longSample(count=1){return `<div class="long-document"><header><small>Glint · 原型示意</small><h2>项目进展记录</h2><p>内容仅用于交互演示，不读取真实屏幕。</p></header>${Array.from({length:count},(_,i)=>`<article><h3>${i+1}. ${['本周工作','方案与进度','数据回顾','下一步计划'][i%4]}</h3><p>保留重要信息，让内容自然连接。</p><div class="document-chart"><i></i><i></i><i></i><i></i></div><p>滚动查看后续内容，右侧同步展示拼接效果。</p><div class="document-lines"></div></article>`).join('')}</div>`;}
function renderScrollSession(m){const b=sourceBox(),pw=Math.min(300,innerWidth*.26),px=b.x+b.w+pw+34<=innerWidth?b.x+b.w+18:b.x-pw-18>=16?b.x-pw-18:innerWidth-pw-16,ph=Math.min(innerHeight-b.y-86,b.h+120);return `<div class="live-session" aria-label="滚动截图"><div class="live-capture-hole" style="left:${b.x}px;top:${b.y}px;width:${b.w}px;height:${b.h}px"><div class="scroll-source" tabindex="0" aria-label="滚动采集区域">${longSample(12)}</div></div><aside class="stitch-preview" style="left:${px}px;top:${b.y}px;width:${pw}px;height:${Math.max(240,ph)}px" aria-label="拼接结果预览"><div class="stitch-image">${m.count?longSample(m.count):'<p class="stitch-loading">正在采集第一帧…</p>'}</div>${m.pending&&m.stopped?`<div class="seam-recovery"><p>部分内容未能拼接，当前展示已对齐部分。片段已保留，可继续采集或主动修复。</p><button data-action="scroll-repair">${m.repair?"收起修复":"调整拼接"}</button>${m.repair?'<button data-action="scroll-discard">丢弃本段</button><button data-action="scroll-accept">应用调整</button>':''}</div>`:''}</aside><div class="live-scroll-control" style="left:${b.x+b.w/2}px;top:${Math.min(innerHeight-110,b.y+b.h-50)}px"><button data-action="scroll-auto" ${m.stopped?'disabled':''}>${m.auto?'Ⅱ 停止滚动':'↓ 自动滚动'}</button><button data-action="scroll-stop">${m.stopped?'继续采集':'结束采集'}</button><small>${m.stopped?'已结束采集，可输出或继续':m.auto?'自动滚动演示':'缓慢滚动选区，自动拼接'}</small></div><div class="live-output-toolbar" style="left:${b.x+b.w/2}px;top:${Math.min(innerHeight-52,b.y+b.h+14)}px">${modeButton('scroll-edit','pen',m.stopped&&m.pending?'编辑已对齐部分':'编辑长截图')}${modeButton('scroll-save','save',m.stopped&&m.pending?'保存已对齐部分':'保存长截图')}${modeButton('scroll-cancel','close','取消滚动截图')}${modeButton('scroll-copy','finish',m.stopped&&m.pending?'复制已对齐部分':'复制长截图')}</div></div>`;}
function renderRecordingSession(){const m=state.modal,p=m.phase||'countdown',b=sourceBox();if(p==='stopped')return `<div class="record-review-backdrop"><section class="record-review" role="dialog" aria-label="录屏预览"><header><b>录屏预览 · ${m.format||'MP4'}</b><small>原型演示，不生成视频文件</small><button data-action="close-modal">×</button></header><div class="record-result-image">${longSample(2)}</div><div class="record-trim"><input type="range" min="0" max="100" value="0" aria-label="录制进度"></div><footer><button data-action="record-play">${m.playing?'Ⅱ':'▶'}</button><span>00:00 / 00:12</span><span class="grow"></span><button data-action="record-download">下载</button><button class="primary" data-action="record-copy">复制到剪贴板</button></footer></section></div>`;return `<div class="live-session record-session"><div class="live-capture-hole" style="left:${b.x}px;top:${b.y}px;width:${b.w}px;height:${b.h}px"></div>${p==='countdown'?'<div class="record-countdown">3</div>':''}<div class="record-control-strip" style="left:${Math.min(innerWidth-440,b.x+b.w-400)}px;top:${Math.min(innerHeight-60,b.y+b.h+12)}px"><span class="record-light"></span><button data-action="record-demo" data-value="${p==='paused'?'active':'paused'}">${p==='paused'?'▶ 继续':'Ⅱ 暂停'}</button><span>${p==='paused'?'已暂停':'00:00'}</span><button class="danger" data-action="record-demo" data-value="stopped">结束录屏</button><button data-action="close-modal" aria-label="放弃录制">×</button><small>原型演示</small></div></div>`;}
let prototypeScrollTimer,prototypeRecordTimer,prototypeWheelTimer;
document.addEventListener('wheel',event=>{if(state.modal?.type!=='scroll-capture'||state.modal.stopped||!event.target.closest('.scroll-source'))return;clearTimeout(prototypeWheelTimer);prototypeWheelTimer=setTimeout(()=>{if(state.modal?.type==='scroll-capture'&&!state.modal.stopped){state.modal.count=Math.min(12,state.modal.count+1);const source=$('.scroll-source'),offset=source?.scrollTop;renderModal();if(source&&$('.scroll-source'))$('.scroll-source').scrollTop=offset;const preview=$('.stitch-image');if(preview)preview.scrollTop=preview.scrollHeight;}},180);},{passive:true});
document.addEventListener('click',event=>{const mode=event.target.closest('[data-mode]')?.dataset.mode;if(mode){if(state.marks.length){toast('请先撤销标注，再切换采集模式。');return;}state.captureMode=mode;state.tool='select';render();}const a=event.target.closest('[data-action]')?.dataset.action;if(a==='scroll-cancel'){clearInterval(prototypeScrollTimer);clearTimeout(prototypeWheelTimer);state.captureMode='capture';state.modal=null;cancelCapture();return;}if(a==='scroll-repair'){state.modal.repair=!state.modal.repair;renderModal();return;}if(['scroll-copy','scroll-save','scroll-edit'].includes(a)&&state.modal?.type==='scroll-capture'){const m=state.modal;m.auto=false;clearInterval(prototypeScrollTimer);if(!m.stopped){m.stopped=true;renderModal();if(m.pending){event.stopImmediatePropagation();toast('部分内容未能拼接，片段已保留。可输出已对齐部分或主动修复。');return;}}}if(a==='scroll-stop'){state.modal.stopped=!state.modal.stopped;state.modal.auto=false;clearInterval(prototypeScrollTimer);renderModal();}if(a==='scroll-auto'){state.modal.auto=!state.modal.auto;clearInterval(prototypeScrollTimer);if(state.modal.auto)prototypeScrollTimer=setInterval(()=>{if(state.modal?.type!=='scroll-capture'||!state.modal.auto||state.modal.stopped){clearInterval(prototypeScrollTimer);return;}state.modal.count++;if(state.modal.count>=8){state.modal.auto=false;clearInterval(prototypeScrollTimer);}renderModal();const preview=$('.stitch-image');if(preview)preview.scrollTop=preview.scrollHeight;},900);renderModal();}if(['scroll-save','scroll-copy','record-download','record-copy'].includes(a))toast('交互演示，不生成文件或修改剪贴板。');if(a==='record-play')toast('原型仅展示播放入口，不模拟视频播放成功。');if(a==='close-modal'){clearInterval(prototypeScrollTimer);clearTimeout(prototypeRecordTimer);}},true);

document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.modal?.type==='scroll-capture'){event.preventDefault();event.stopImmediatePropagation();clearInterval(prototypeScrollTimer);clearTimeout(prototypeWheelTimer);state.captureMode='capture';state.modal=null;cancelCapture();}},true);
